    # Translate each nonzero cell/object toward the right edge, packing objects
    # without changing their row coordinates. Objects preserve their shape.
    h, w = len(grid), len(grid[0])
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(y+dy,x+dx)
                    if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==color:
                        seen.add(z); q.append(z)
            comps.append((color,cells))
    out=[[0]*w for _ in range(h)]
    for color,cells in comps:
        shift=w-1-max(x for y,x in cells)
        for y,x in cells: out[y][x+shift]=color
    return out
